INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',1,'Глоссарий','Коротко изучи основные термины: BP — давление, HR — частота сердечных сокращений, OD — передозировка, CPR — СЛР. Остальные термины описаны в шпаргалке. После теории — только вопросы этого блока.',NULL,1,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что означает HR?','["Частота сердечных сокращений","Артериальное давление","Передозировка"]',0,'HR — частота сердечных сокращений.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=1;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что означает CPR?','["Сердечно-лёгочная реанимация","Передозировка","Период полувыведения"]',0,'CPR — сердечно-лёгочная реанимация.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=1;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'В какие дни/ивенты есть ACE Medical?','["Пятница — TvT","Только понедельник","Каждый день"]',0,'Правильный ответ для RRT: Пятница — TvT.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=1;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',2,'Медикаменты','Запомни базовое назначение препаратов: эпинефрин — сердце, метопролол — слишком высокий HR, морфин — боль при соблюдении условий, налоксон — OD морфином, фенилэфрин — низкое BP, аммоний — стабильный без сознания после остановки кровотечения.',NULL,2,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что используют при OD морфином?','["Налоксон","Аммоний","Метопролол"]',0,'Налоксон применяется при признаках передозировки морфином.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=2;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что применяют при высоком HR, если это не арест?','["Метопролол","Морфин","Аммоний"]',0,'В шпаргалке: высокий HR → метопролол.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=2;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Для чего нужен фенилэфрин?','["Поднять BP","Снять боль","Вернуть сознание"]',0,'Фенилэфрин — вазопрессор для низкого BP.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=2;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',3,'Витальные показатели','Ориентиры ACE из шпаргалки: Stable — HR 40–220; Unstable — HR <40; Critical — HR <30. Cardiac Arrest: HR <20 или >220. Кровопотеря делится на классы I–IV.',NULL,3,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Какой HR в шпаргалке считается тахи-арестом?','["Больше 220","40–80","Меньше 40"]',0,'Тахи-арест: HR >220.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=3;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что означает кровопотеря класса IV?','["80%","30%","10%"]',0,'Класс IV — 80% по таблице.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=3;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делать при критическом состоянии по базовой схеме?','["Физраствор + фенилэфрин, готовиться к аресту","Дать морфин","Сразу аммоний"]',0,'Так указано в таблице состояний.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=3;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',4,'Resilience','Порог потери сознания в ACE-шпаргалке — ниже 34/100. Восстановление возможно при стабильных виталах. Аммоний ускоряет подъём Resilience, но не работает при нестабильных виталах или активном кровотечении.',NULL,4,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'При каком Resilience человек теряет сознание по этой ACE-логике?','["Ниже 34/100","Ниже 80/100","Только при 0/100"]',0,'Порог: <34/100.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=4;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Можно ли дать аммоний при активном кровотечении?','["Нет","Да, всегда","Только при HR >220"]',0,'Сначала нужно остановить кровотечение и стабилизировать виталы.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=4;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что важно перед аммонием?','["Стабильные виталы и закрытое кровотечение","Чтобы пациент обязательно был в сознании","Чтобы BP было максимальным"]',0,'Аммоний используется для стабильного пациента без сознания после остановки кровотечения.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=4;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',5,'Кровотечение','Запомни простое правило: I — бинт ×1, II — бинт ×2 или давящая повязка, III — давящая повязка/жгут на конечности, IV — жгут немедленно, затем бинты. Приоритет — сначала сильное артериальное кровотечение.',NULL,5,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Чем закрыть кровотечение I степени?','["1 бинтом","Только жгутом","Ничем"]',0,'Класс I — Bandage ×1.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=5;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делать при кровотечении IV степени?','["Жгут немедленно, затем бинты","Только морфин","Аммоний"]',0,'Класс IV — жгут сразу, затем бинты.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=5;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что в первую очередь важнее при сильном артериальном кровотечении?','["Остановить его жгутом","Дать морфин","Проверить Resilience"]',0,'Приоритет — остановить массивное кровотечение.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=5;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',6,'Правила лечения и СЛР','Главные правила: остановка сердца → СЛР + эпинефрин; между дозами эпинефрина минимум 1 минута; морфин — в сознании и через ≥15 минут; OD морфином → налоксон; аммоний — только стабильному без сознания после остановки кровотечения.',NULL,6,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Через сколько минимум можно повторить эпинефрин?','["Через 1 минуту","Через 5 секунд","Сразу"]',0,'R2: не раньше чем через 1 минуту.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=6;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Можно ли дать морфин через 8 минут после предыдущей дозы?','["Нет","Да","Только если пациент без сознания"]',0,'Нужно ждать минимум 15 минут.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=6;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делать при остановке сердца по базовому правилу?','["СЛР + эпинефрин","Только морфин","Только аммоний"]',0,'R1: СЛР + эпинефрин.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=6;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',7,'Алгоритм действий','Базовый порядок: проверить кровотечение → сознание → остановку сердца → стабильность виталов → боль → долечить аптечкой. Не перескакивай сразу к лекарствам.',NULL,7,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что проверяем первым в алгоритме?','["Есть ли кровотечение","Есть ли боль","Resilience"]',0,'Первый шаг — кровотечение.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=7;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что идёт после проверки сознания, если пациент без сознания?','["Проверка остановки сердца","Сразу морфин","Сразу аммоний"]',0,'Дальше проверяется остановка сердца.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=7;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делаем в конце?','["Долечиваем аптечкой до полного восстановления","Даем морфин всем","Повторяем жгут навсегда"]',0,'Последний шаг — долечить аптечкой.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=7;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',8,'Quick Reference','Используй правило «Если → то → осторожно»: высокий HR → метопролол; низкое BP + кровит → фенилэфрин + бинты; без сознания и виталы стабильны → аммоний; OD → налоксон; III–IV кровотечение → жгут → бинты.',NULL,8,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'HR высокий, но это не арест. Что выбрать?','["Метопролол","Налоксон","Аммоний"]',0,'Высокий HR без ареста → метопролол.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=8;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'BP низкий и пациент кровит. Что выбрать?','["Фенилэфрин + бинты","Морфин","Только аммоний"]',0,'В Quick Reference указано: низкое BP + кровит → фенилэфрин + бинты.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=8;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Дыхание угнетено после морфина. Что подозреваем?','["OD и даём налоксон","Нужно дать ещё морфин","Нужно дать аммоний"]',0,'Угнетение дыхания после морфина — признак OD.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=8;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('ace_medical',9,'Типичные ошибки','Не делай три вещи: не давай морфин при нестабильных виталах/без сознания, не колоти эпинефрин пачкой без пауз, не используй аммоний при активном кровотечении. Также СЛР при живом пульсе запрещена этой схемой.',NULL,9,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Можно ли давать морфин пациенту без сознания?','["Нет","Да, всегда","Только при низком BP"]',0,'В шпаргалке это указано как типичная ошибка.',1 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=9;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что будет проблемой при эпинефрине без пауз?','["Можно загнать в тахи-арест","Ничего","Только станет холодно"]',0,'Частый эпинефрин может привести к HR >220.',2 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=9;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Работает ли аммоний при активном кровотечении?','["Нет","Да","Только при 100/100 Resilience"]',0,'Он не работает при активном кровотечении.',3 FROM guide_blocks WHERE guide_key='ace_medical' AND block_no=9;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',1,'Маршевый порядок в лесу','В лесном маршевом порядке соблюдай сектора и дистанции. На схеме из материала показаны пулемёт, КО, радист, РПГ, снайпер, головной и тыловой дозоры; дистанции 5–7 и 10–12 м.','assets/movement/movement-02.jpg',1,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Какая дистанция указана для пары/элемента ближе к 5–7 м?','["5–7 м","20–25 м","1–2 м"]',0,'В схеме указано 5–7 метров.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=1;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Кто обозначен впереди построения?','["Головной дозор","Тыловой дозор","Снайпер"]',0,'В материале есть отдельное обозначение головного дозора.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=1;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что важно держать в марше?','["Свои сектора осмотра","Всегда идти по центру дороги","Бежать впереди всех"]',0,'Материал отдельно показывает сектора осмотра.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=1;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',2,'Узкая лесополоса','Если лесополоса узкая, по краям кусты/деревья, а середина свободна — занимай левую или правую сторону согласно секторам обзора. Для TvT радист и КО идут по одной стороне для оперативности.',NULL,2,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Где идти в узкой лесополосе?','["Слева или справа согласно секторам","Строго по центру","Только по дороге"]',0,'Так сформулировано правило в материале.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=2;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Кто в TvT должен идти по одной стороне?','["Радист и КО","Снайпер и тыловой дозор","Все по одному"]',0,'Уточнение материала — радист с КО по одной стороне.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=2;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Главная цель такого построения?','["Сохранять сектора и порядок движения","Собраться в одну точку","Увеличить бег"]',0,'Правило связано с секторами обзора и оперативностью.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=2;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',3,'Контакт / засада','При контакте головной дозор разрывает дистанцию, ищет укрытие, докладывает направление и открывает огонь. Основное тело занимает укрытия; головной дозор отходит под дымами и прикрытием. Тыловой дозор флангует, если КО не запретил. В контакте — укрытие, без беготни в полный рост.','assets/movement/movement-05.jpg',3,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делает головной дозор сразу после контакта?','["Ищет укрытие и докладывает направление","Бежит прямо к противнику","Уходит без доклада"]',0,'Именно это указано в пояснении.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=3;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Когда тыловой дозор не флангует?','["Когда КО сказал не фланговать","Всегда","Только ночью"]',0,'КО может запретить флангование.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=3;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Как двигаться под огнём?','["В укрытии, максимум в приседе","В полный рост","Только бегом"]',0,'Материал прямо запрещает беготню в полный рост.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=3;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',4,'Прочёска / триггер','При ожидаемом контакте отряд делится на двойки. Нельзя идти двойками на одной линии; соседние двойки должны быть в поле видимости. В двойке передний и задний меняются ролями при движении/отходе.','assets/movement/movement-06.jpg',4,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Как формируется отряд при прочёске?','["На двойки","На одиночек без связи","В одну длинную колонну без пар"]',0,'Материал: отряд делится на 2-ки.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=4;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Какая дистанция внутри двойки указана?','["5–7 м","30–40 м","1 м"]',0,'Передний идёт на 5–7 метров впереди.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=4;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делают соседние двойки?','["Держат друг друга в поле видимости","Идут строго на одной линии","Не смотрят друг на друга"]',0,'Это отдельно подчеркнуто в материале.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=4;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',5,'Триггер со зданиями','При подходе к зданиям используются дымы и сектора прикрытия. Две двойки держат сектора вокруг дома, другие смотрят спины/360°, следующая двойка подходит к дому и начинает «прогрев». В CQB не толпятся: один заходит, другой контролирует/готов к размену.','assets/movement/movement-08.jpg',5,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что используется при перебежке от забора к первому зданию?','["Дымы","Только бег","Только голос"]',0,'Материал прямо говорит о дыме.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=5;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делают прикрывающие двойки?','["Держат сектора вокруг дома и смотрят спины/360°","Все заходят одновременно","Уходят далеко назад"]',0,'Так описана организация прикрытия.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=5;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Как заходят в CQB?','["Не толпятся: один заходит, второй контролирует","Все одновременно в одну дверь","Только снайпер"]',0,'В материале указан принцип одного заходящего и второго на контроле/размене.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=5;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',6,'Движение в траншеях','В траншеях также работают двойками. Одна двойка держит тыл. На длинной прямой одна пара держит угол, другая двигается. Средние пары по возможности проверяют верх траншеи.','assets/movement/movement-09.jpg',6,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Как двигаются по траншеям?','["Двойками","Только по одному","Всем отрядом плечом к плечу"]',0,'Материал: двигаетесь так же в 2-ках.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=6;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делает одна двойка постоянно?','["Держит тыл","Идёт первой всегда","Уходит в сторону"]',0,'Одна двойка всегда держит тыл.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=6;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делают пары в середине звена по возможности?','["Выглядывают сверху на траншеи","Останавливаются полностью","Идут только назад"]',0,'Они проверяют, не обходят ли сверху.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=6;
INSERT INTO guide_blocks(guide_key,block_no,title,theory,image_url,sort_order,active) VALUES ('movement',7,'Точка сбора и неразбериха','При засаде полезно заранее отмечать точки сбора на карте. Если регрупп организовать под огнём не получается, каждый выходит из огня как может и возвращается на согласованную точку сбора.','assets/movement/movement-10.jpg',7,1);
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что стоит отмечать на карте при движении?','["Точки сбора","Только врагов","Только транспорт"]',0,'Материал рекомендует отмечать точки сбора.',1 FROM guide_blocks WHERE guide_key='movement' AND block_no=7;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Что делать, если под огнём не получается организованно сделать регруп?','["Выйти из огня как можешь и вернуться на точку сбора","Остановиться на месте","Все бежать в одну сторону без точки"]',0,'Это прямо указано в материале.',2 FROM guide_blocks WHERE guide_key='movement' AND block_no=7;
INSERT INTO guide_questions(block_id,question,options_json,correct_index,explanation,sort_order) SELECT id,'Зачем нужна точка сбора?','["Чтобы восстановить порядок после засады/неразберихи","Чтобы все стояли там весь бой","Чтобы заменить рацию"]',0,'Она нужна для организованного возвращения и регруппа.',3 FROM guide_blocks WHERE guide_key='movement' AND block_no=7;
